import pandas as pd
import itertools
import numpy as np

def task_func(animals=None, foods=None):
    is_animals_empty = animals is None or len(animals) == 0
    is_foods_empty = foods is None or len(foods) == 0

    if is_animals_empty and is_foods_empty:
        return pd.DataFrame()

    if is_animals_empty:
        animals = ['Dog', 'Cat', 'Bird', 'Fish', 'Lamb']
    if is_foods_empty:
        foods = ['Meat', 'Fish', 'Grain', 'Vegetables', 'Seeds']

    combos = list(itertools.product(animals, foods))
    np.random.shuffle(combos)

    df = pd.DataFrame(index=animals, columns=foods)
    for a, f in combos:
        df.at[a, f] = f"{a}:{f}"

    return df
